package dev.spaceclient.hud;
import java.nio.file.*;
import java.util.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class HudGroupEditingTest {
    private Map<HudModule,HudPlacement> sample(){Map<HudModule,HudPlacement> p=new EnumMap<>(HudModule.class);p.put(HudModule.FPS,new HudPlacement(HudPlacement.Horizontal.LEFT,HudPlacement.Vertical.TOP,20,25,1));p.put(HudModule.CPS,new HudPlacement(HudPlacement.Horizontal.LEFT,HudPlacement.Vertical.TOP,110,60,1));p.put(HudModule.CLOCK,new HudPlacement(HudPlacement.Horizontal.LEFT,HudPlacement.Vertical.TOP,230,100,1));return p;}
    private Map<HudModule,HudPlacement.Bounds> bounds(Map<HudModule,HudPlacement> p){Map<HudModule,HudPlacement.Bounds>b=new EnumMap<>(HudModule.class);for(HudModule m:p.keySet())b.put(m,p.get(m).resolve(320,240,m==HudModule.CPS?40:20,10));return b;}
    @Test public void groupClampPreservesSpacingInsteadOfSquashingAtScreenEdges(){Map<HudModule,HudPlacement> p=sample();Map<HudModule,HudPlacement> n=HudLayoutOperations.move(p,bounds(p),p.keySet(),Collections.emptySet(),1000,-1000,320,240);Map<HudModule,HudPlacement.Bounds>b=bounds(n);assertEquals(90,b.get(HudModule.CPS).x-b.get(HudModule.FPS).x,0);assertEquals(0,b.get(HudModule.FPS).y,0);assertEquals(320,b.get(HudModule.CLOCK).x+b.get(HudModule.CLOCK).width,0);}
    @Test public void alignUsesSharedEdgesAndSkipsLockedWidgets(){Map<HudModule,HudPlacement>p=sample();Set<HudModule>locked=EnumSet.of(HudModule.CLOCK);Map<HudModule,HudPlacement>n=HudLayoutOperations.align(p,bounds(p),p.keySet(),locked,HudLayoutOperations.Align.RIGHT,320,240);assertSame(p.get(HudModule.CLOCK),n.get(HudModule.CLOCK));Map<HudModule,HudPlacement.Bounds>b=bounds(n);assertEquals(b.get(HudModule.FPS).x+b.get(HudModule.FPS).width,b.get(HudModule.CPS).x+b.get(HudModule.CPS).width,0);assertEquals(25,b.get(HudModule.FPS).y,0);}
    @Test public void distributionKeepsEndpointsAndEqualVisibleGapsForUnequalWidths(){Map<HudModule,HudPlacement>p=sample();Map<HudModule,HudPlacement>n=HudLayoutOperations.distribute(p,bounds(p),p.keySet(),Collections.emptySet(),true,320,240);Map<HudModule,HudPlacement.Bounds>b=bounds(n);assertEquals(20,b.get(HudModule.FPS).x,0);assertEquals(230,b.get(HudModule.CLOCK).x,0);double gap=b.get(HudModule.CPS).x-b.get(HudModule.FPS).x-b.get(HudModule.FPS).width;assertEquals(gap,b.get(HudModule.CLOCK).x-b.get(HudModule.CPS).x-b.get(HudModule.CPS).width,0);}
    @Test public void layoutHistoryBranchesAndOnlyAdvancesAfterSuccess(){Map<HudModule,HudPlacement>a=sample(),b=HudLayoutOperations.move(a,bounds(a),a.keySet(),Collections.emptySet(),1,1,320,240);HudLayoutHistory h=new HudLayoutHistory();h.record(a,b);assertTrue(HudLayoutHistory.same(a,h.undo()));assertTrue(h.canUndo());assertFalse(h.canRedo());h.didUndo(b);assertTrue(h.canRedo());assertTrue(HudLayoutHistory.same(b,h.redo()));h.didRedo(a);h.didUndo(b);h.record(a,HudLayoutOperations.move(a,bounds(a),a.keySet(),Collections.emptySet(),2,2,320,240));assertFalse(h.canRedo());h.clear();assertFalse(h.canUndo());}
    @Test public void batchSaveRestoresEveryPlacementAfterWriteFailure()throws Exception{Path parent=Files.createTempDirectory("space-group-rollback"),file=parent.resolve("hud");HudSettings s=HudSettings.open(file);Map<HudModule,HudPlacement>before=HudLayoutOperations.snapshot(s.getConfig().active());Files.createDirectory(file);assertFalse(s.placeAll(sample()));assertTrue(HudLayoutHistory.same(before,HudLayoutOperations.snapshot(s.getConfig().active())));assertTrue(Files.isDirectory(file));}
    @Test public void batchSaveAndVisibilityKeepOtherProfileAndImportExport()throws Exception{Path parent=Files.createTempDirectory("space-group-save"),file=parent.resolve("hud");HudSettings s=HudSettings.open(file);Map<HudModule,HudPlacement>other=HudLayoutOperations.snapshot(s.getConfig().profile(1));assertTrue(s.placeAll(sample()));assertTrue(s.visibility(EnumSet.of(HudModule.CPS,HudModule.CLOCK),false));assertTrue(s.exportProfile());Files.copy(parent.resolve("spaceclient-hud-export.properties"),parent.resolve("spaceclient-hud-import.properties"));assertTrue(s.importProfile());assertTrue(HudLayoutHistory.same(other,HudLayoutOperations.snapshot(s.getConfig().profile(1))));HudSettings reopened=HudSettings.open(file);assertEquals(230,reopened.getConfig().active().placement(HudModule.CLOCK).x,0);assertFalse(reopened.getConfig().active().clock);}
    @Test public void numericLimitsDescribeVisibleTopLeftRangeAtOneAndThreeTimesScale(){for(double scale:new double[]{1,3}){HudPlacement p=new HudPlacement(HudPlacement.Horizontal.LEFT,HudPlacement.Vertical.TOP,0,0,scale);HudPlacement.Bounds b=p.resolve(320,240,61,11);assertEquals((int)Math.round(320-b.width),HudArrangeScreen.coordinateLimit(320,b.width));assertEquals((int)Math.round(240-b.height),HudArrangeScreen.coordinateLimit(240,b.height));HudPlacement.Bounds edge=p.at(320-b.width,240-b.height,320,240,61,11,false).resolve(320,240,61,11);assertEquals(320,edge.x+edge.width,0);assertEquals(240,edge.y+edge.height,0);}}
    @Test public void fittedInventoryAtThreeTimesScaleHasSafeDisabledAxis(){HudPlacement p=new HudPlacement(HudPlacement.Horizontal.LEFT,HudPlacement.Vertical.TOP,0,0,3);HudPlacement.Bounds b=p.resolve(427,240,InventoryHud.WIDTH,InventoryHud.height(false));int x=HudArrangeScreen.coordinateLimit(427,b.width),y=HudArrangeScreen.coordinateLimit(240,b.height);assertTrue(x==0||y==0);dev.spaceclient.settings.SettingRow row=HudArrangeScreen.coordinateRow(0,"X","Position",0,0,"Axis filled");assertFalse(row.enabled);assertEquals("Axis filled",row.detail);assertEquals(0,row.range.min);assertEquals(1,row.range.max);assertTrue(Double.isFinite(row.range.fraction(0)));}
}
